void sig_handler(int sig) { 
    // Exceptional Control Flow (ECF) entry point
    // Triggered by kernel interrupt/trap handling
    if (sig == 11) { /* SIGSEGV */
        // Syscall used asynchronously within the handler
        write(2, "ECF: SIGSEGV caught\n", 20);
    }
}

struct sigaction sa = {0};
sa.sa_handler = sig_handler;
sa.sa_flags = SA_RESTART; 

// Syscall registration: ECF handler setup
// Registers handler function pointer in Kernel Space (PCB)
int result = sigaction(SIGSEGV, &sa, NULL); 

// Syscall invocation switches execution mode (User -> Kernel)
ssize_t bytes_written = write(1, "Start\n", 6);
// The 'write' function executes the underlying trap instruction
// Trap is an intentional, synchronous form of ECF
